import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"ChatGPT Sites","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/sites.md","filePath":"products/ai-coding/codex/sites.md","lastUpdated":1787110548000}'),n={name:"products/ai-coding/codex/sites.md"};function o(r,e,d,h,l,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="chatgpt-sites" tabindex="-1">ChatGPT Sites <a class="header-anchor" href="#chatgpt-sites" aria-label="Permalink to &quot;ChatGPT Sites&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — turn a prompt (or a compatible local project) into a <strong>hosted</strong> website or app. Sites is a public-beta product next to ChatGPT Work, not a footnote. Every deploy URL is production.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/sites" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/sites</a>. Docs: <a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a>. Manage: <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Account</td><td>A ChatGPT plan that includes Sites. Limits are plan-wide during the beta — <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">pricing</a></td></tr><tr><td>Surface</td><td>ChatGPT <strong>web</strong> or the <strong>desktop app</strong>. CLI and IDE have <strong>no</strong> Sites management UI</td></tr><tr><td>Optional</td><td>A local project you will publish; Codex CLI / IDE can still edit that source</td></tr></tbody></table><p>Availability depends on plan, region, and workspace settings. Hitting a limit can block a new Site, extra storage, or a high-usage public Site; you can still edit existing ones.</p><p><strong>Learning objectives</strong>: start a Site from a prompt; save a version before deploy; pick access; know D1 / R2 vs no storage.</p><p><strong>Non-goals</strong>: treating Sites as your production frontend stack; Claude Design-style brand import (that product does not exist here); CLI sandbox (<a href="./codex-cli.html">CLI</a>).</p><h2 id="what-sites-is-—-and-is-not" tabindex="-1">What Sites is — and is not <a class="header-anchor" href="#what-sites-is-—-and-is-not" aria-label="Permalink to &quot;What Sites is — and is not&quot;">​</a></h2><p>Sites lets ChatGPT <strong>create, host, refine, and share</strong> websites, web apps, and games. Mention <code>website</code> or <code>@Sites</code> to start the workflow. A Site is a persistent hosted output. It survives the Work chat that created it. It is <strong>not</strong> a ChatGPT Project.</p><p>It is <strong>not</strong>:</p><ul><li>Claude Design. There is no official “import a design system from the repo, then hand off a bundle” product.</li><li>Staging. The deployment URL is live for the chosen audience.</li><li>A Codex CLI or IDE panel. Create, save, deploy, and manage on the web or desktop. Use CLI / IDE only to edit and test the local source.</li></ul><p>Work still owns the knowledge-work agent. This page is the Sites product. Work’s short Sites note lives in <a href="./chatgpt-work.html#sites-when-you-need-a-hosted-page">ChatGPT Work</a>.</p><h2 id="where-to-open-it" tabindex="-1">Where to open it <a class="header-anchor" href="#where-to-open-it" aria-label="Permalink to &quot;Where to open it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>How</th></tr></thead><tbody><tr><td>Web</td><td><strong>More → Sites</strong>, or <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></td></tr><tr><td>Desktop</td><td>Open <strong>Sites</strong> in the ChatGPT desktop app</td></tr><tr><td>CLI / IDE</td><td>No management view. Edit the local project there; publish from web or desktop</td></tr></tbody></table><h2 id="first-site-15-minutes" tabindex="-1">First Site (15 minutes) <a class="header-anchor" href="#first-site-15-minutes" aria-label="Permalink to &quot;First Site (15 minutes)&quot;">​</a></h2><h3 id="_1-describe-the-audience-and-the-result" tabindex="-1">1. Describe the audience and the result <a class="header-anchor" href="#_1-describe-the-audience-and-the-result" aria-label="Permalink to &quot;1. Describe the audience and the result&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build a project request dashboard for my operations team. Let team members</span></span>
<span class="line"><span>submit requests, see who owns each one, update the status, and filter the list.</span></span>
<span class="line"><span>Require people to sign in with their workspace account, and keep the request</span></span>
<span class="line"><span>data saved between visits.</span></span></code></pre></div><h3 id="_2-review-behavior-not-just-the-screenshot" tabindex="-1">2. Review behavior, not just the screenshot <a class="header-anchor" href="#_2-review-behavior-not-just-the-screenshot" aria-label="Permalink to &quot;2. Review behavior, not just the screenshot&quot;">​</a></h3><p>Check content, data handling, and the signed-in vs signed-out path.</p><h3 id="_3-refine" tabindex="-1">3. Refine <a class="header-anchor" href="#_3-refine" aria-label="Permalink to &quot;3. Refine&quot;">​</a></h3><p>Say the change. Attach files or a screenshot when that is the evidence.</p><p>On the web preview, <strong>Edit → Describe website edits</strong>. Use <strong>Screenshot</strong> or <strong>Add files and more</strong> when extra context helps.</p><h3 id="_4-save-a-version-then-deploy" tabindex="-1">4. Save a version, then deploy <a class="header-anchor" href="#_4-save-a-version-then-deploy" aria-label="Permalink to &quot;4. Save a version, then deploy&quot;">​</a></h3><p>Two stages (desktop / local project):</p><ol><li><strong>Save a version</strong> — a reviewable candidate. For a local source project, the version ties to the Git commit used for the build.</li><li><strong>Deploy a version</strong> — publishes that candidate and returns the production URL.</li></ol><p>If you want to review first, ask ChatGPT to <strong>save a version without deploying</strong>.</p><h3 id="_5-share-with-the-narrowest-audience" tabindex="-1">5. Share with the narrowest audience <a class="header-anchor" href="#_5-share-with-the-narrowest-audience" aria-label="Permalink to &quot;5. Share with the narrowest audience&quot;">​</a></h3><p>A new Site is limited to the owner and workspace admins until you change access.</p><h2 id="projects-versions-and-openai-hosting-json" tabindex="-1">Projects, versions, and <code>.openai/hosting.json</code> <a class="header-anchor" href="#projects-versions-and-openai-hosting-json" aria-label="Permalink to &quot;Projects, versions, and \`.openai/hosting.json\`&quot;">​</a></h2><p>On desktop / local projects, Sites stores linkage and optional storage binding names in <code>.openai/hosting.json</code>. A new starter may omit <code>project_id</code> until hosting is provisioned.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;project_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;project-id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;d1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;r2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Do <strong>not</strong> put secrets in this file. Hosted env vars live in the Site’s <strong>Settings</strong>. Keep local <code>.env</code> / <code>.env.example</code> aligned for keys only.</p><p>Publish a compatible existing app:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deploy this project with Sites. Check whether it is compatible, make any</span></span>
<span class="line"><span>required changes, and give me the deployment URL.</span></span></code></pre></div><h2 id="pick-a-site-shape" tabindex="-1">Pick a site shape <a class="header-anchor" href="#pick-a-site-shape" aria-label="Permalink to &quot;Pick a site shape&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Ask Sites for</th></tr></thead><tbody><tr><td>Landing page / content</td><td>No persistent app state unless required</td></tr><tr><td>Saved records, scores, progress</td><td><strong>D1</strong> (relational)</td></tr><tr><td>Uploads (images, docs, media)</td><td><strong>R2</strong> (object storage)</td></tr><tr><td>Uploads plus searchable metadata</td><td>D1 + R2</td></tr><tr><td>Internal, current workspace user</td><td>Workspace-authenticated identity</td></tr><tr><td>Public sign-in</td><td>Authentication-enabled Site</td></tr></tbody></table><p>Do not request durable storage for a theme toggle. Do request it for data people expect to survive a refresh.</p><h2 id="access-sign-in-with-chatgpt-domains" tabindex="-1">Access, Sign in with ChatGPT, domains <a class="header-anchor" href="#access-sign-in-with-chatgpt-domains" aria-label="Permalink to &quot;Access, Sign in with ChatGPT, domains&quot;">​</a></h2><p>Sharing lets people <strong>visit</strong>. It does not let them edit.</p><p>Typical options (depends on account and workspace): owner + admins; selected users or groups; anyone in the workspace; anyone on the internet (only if public publishing is on). Enterprise public publishing is <strong>off</strong> by default.</p><p>Workspace-restricted Sites already use ChatGPT identity. A public Site can stay open and add optional <strong>Sign in with ChatGPT</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add Sign in with ChatGPT to this public Site. Keep the Site available to</span></span>
<span class="line"><span>signed-out visitors. After they sign in, greet them with their full name</span></span>
<span class="line"><span>when available, or their email address otherwise. Keep authorization</span></span>
<span class="line"><span>decisions in server-side code.</span></span></code></pre></div><p>Platform paths: <code>/signin-with-chatgpt</code>, <code>/signout-with-chatgpt</code>. Identity arrives as <code>oai-authenticated-user-email</code> and optional <code>oai-authenticated-user-full-name</code>. Authorize on the server.</p><p>Custom domains (where available): you already own the apex or subdomain; Sites does not register DNS. Not available in Enterprise at launch. Add the records Sites shows, wait, refresh status.</p><h2 id="analytics-and-teardown" tabindex="-1">Analytics and teardown <a class="header-anchor" href="#analytics-and-teardown" aria-label="Permalink to &quot;Analytics and teardown&quot;">​</a></h2><p>Traffic is recorded without an analytics SDK: unique visitors and page views over time. Open the Site → <strong>More actions → Analytics</strong>. Not available for Sites owned by an Enterprise workspace.</p><p>To unpublish without delete: tighten sharing and confirm the old audience cannot open it.</p><p>To delete: <strong>Delete site</strong> → type the slug → <strong>Permanently delete</strong>. There is no restore.</p><h2 id="limits-and-unsupported-uses" tabindex="-1">Limits and unsupported uses <a class="header-anchor" href="#limits-and-unsupported-uses" aria-label="Permalink to &quot;Limits and unsupported uses&quot;">​</a></h2><p>Sites runs in a supported runtime. Some frameworks, private networks, databases, background services, and hosting patterns are out.</p><p>No data residency or inference residency at launch — including Site code, D1 / R2, artifacts, and logs.</p><p><strong>NEVER</strong> use Sites for PHI, payment-card data, children under 13 (or the applicable age of consent), financial transactions, malware, phishing, impersonation, or other policy violations. Current policy: <a href="https://help.openai.com/en/articles/20001339" target="_blank" rel="noreferrer">Creating and managing ChatGPT Sites</a>.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Deploying to “preview”</td><td>The URL is production</td><td>Save a version; deploy after review</td></tr><tr><td>Looking for Sites in the CLI</td><td>There is no management UI</td><td>Web or desktop</td></tr><tr><td>Putting secrets in prompts or <code>hosting.json</code></td><td>Leak</td><td>Site <strong>Settings</strong> for hosted secrets</td></tr><tr><td>Treating Sites as the production app platform</td><td>Runtime / residency / policy limits</td><td>Use it for internal tools and betas; keep real prod elsewhere</td></tr><tr><td>Confusing a Site with a ChatGPT Project</td><td>Wrong list, wrong lifetime</td><td>Sites list at <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>A frontend team ships an internal request board: describe the audience, require workspace sign-in, ask for D1 so rows persist, save a version, have one teammate open the URL, then deploy. Implement the long-lived component library in the repo with <a href="./codex-cli.html">Codex</a>; use Sites for the hosted shell, not as the design system.</p><p>Showcase (prompts and live apps): <a href="https://developers.openai.com/showcase" target="_blank" rel="noreferrer">developers.openai.com/showcase</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Work vs Codex vs Sites → <a href="./">Learning Map</a></li><li>Work agent (decks, plugins, schedule) → <a href="./chatgpt-work.html">ChatGPT Work</a></li><li>Local source + review pane → <a href="https://learn.chatgpt.com/docs/code-review?surface=app" target="_blank" rel="noreferrer">Code review</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/sites" target="_blank" rel="noreferrer">Sites (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites (docs)</a></li><li><a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></li><li><a href="https://help.openai.com/en/articles/20001339" target="_blank" rel="noreferrer">Creating and managing ChatGPT Sites</a></li><li><a href="https://help.openai.com/en/articles/20001340" target="_blank" rel="noreferrer">Privacy / data-protection</a></li></ul>`,61)])])}const k=t(n,[["render",o]]);export{m as __pageData,k as default};
